private int parseEndOfLine(String headerPart, int end) throws InvalidInputException {

    // Check if the input is valid
    if (headerPart.length() >= end) {
        throw new InvalidInputException("Invalid input: end index exceeds string length");
    }

    // Check if the input contains the \r\n sequence
    int eolIndex = -1;
    for (int i = end - 1; i >= 0; i--) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            eolIndex = i;
            break;
        }
    }

    // If the \r\n sequence is not found, return the end index
    if (eolIndex == -1) {
        return end;
    }

    // Return the index of the \r\n sequence
    return eolIndex;
}

private int parseEndOfLine(String headerPart, int end) {
  // Check if the end of the string has been reached
  if (end >= headerPart.length()) {
    return end;
  }

  // Search for the '\r\n' sequence indicating the end of the line
  int i = end;
  while (i < headerPart.length() && (headerPart.charAt(i) != '\r' || headerPart.charAt(i + 1) != '\n')) {
    i++;
  }

  // Return the index of the '\r\n' sequence if found, or the end of the string otherwise
  if (i < headerPart.length()) {
    return i + 1;
  } else {
    return end;
  }
}

