public void addNewTarget(Channels channels, IConsumer consumer) {
    // Validate the input
    if (channels == null) {
        throw new IllegalArgumentException("channels cannot be null");
    }
    if (consumer == null) {
        throw new IllegalArgumentException("consumer cannot be null");
    }

    // Add the new target
    synchronized (this) {
        this.targets.add(channels);
    }

    // Start consuming messages from the new target
    new Thread(() -> {
        try {
            while (true) {
                Message message = channels.take();
                consumer.accept(message);
            }
        } catch (InterruptedException e) {
            // Ignore the interrupt and continue
        }
    }).start();
}

