        int offsetOfLongValue = offset + 4;

        // Read the 4 bytes as an integer
        int intValue = readInt(offsetOfLongValue);

        // Calculate the offset of the next 4 bytes to be read
        int offsetOfSecondLongValue = offsetOfLongValue + 4;

        // Read the next 4 bytes as an integer
        int secondIntValue = readInt(offsetOfSecondLongValue);

        // Combine the two integers into a long value
        long longValue = ((long) intValue << 32) | (secondIntValue & 0xFFFFFFFFL);

        return longValue;
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid offset for reading a long value", e);
