    String telnetMessage = message.replace('\n', '\r').replace('\r', '\n');

    // Step 3: Send message to each client
    for (int i = 0; i < clients.size(); i++) {
        try {
            clients.get(i).send(telnetMessage);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

