protected List<TimeRange> buildTimeRanges(long start, long end){
  List<TimeRange> timeRanges = new ArrayList<>();
  long fetchDataDuration = 86400; // 24 hours

  if(start > end){
    throw new IllegalArgumentException("Start time must be less than or equal to end time");
  }

  while(start < end){
    long duration = Math.min(fetchDataDuration, end - start);
    timeRanges.add(new TimeRange(start, start + duration));
    start += duration;
  }

  return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {

  List<TimeRange> timeRanges = new ArrayList<>();
  long currentStart = start;
  long currentEnd = end;

  while (currentStart < currentEnd) {
    long duration = currentEnd - currentStart;
    if (duration > FETCH_DATA_DURATION) {
      currentEnd = currentStart + FETCH_DATA_DURATION;
    }
    timeRanges.add(new TimeRange(currentStart, currentEnd));
    currentStart += FETCH_DATA_DURATION;
  }

  return timeRanges;
}

