    }

    int daysInMonth = getDaysInMonth(year, week);
    if (day > daysInMonth) {
        return -1;
    }

    long compressedTimeBucket = (year * 1000000) + (week * 10000) + (day * 100);
    return compressedTimeBucket;
}

static int getDaysInMonth(long year, long week) {
    int daysInMonth = 0;
    if (isLeapYear(year)) {
        daysInMonth = 28;
    } else {
        daysInMonth = 29;
    }
    if (week == 12) {
        daysInMonth += 3;
    }
    return daysInMonth;
}

static boolean isLeapYear(long year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

