public static long compressTimeBucket(long timeBucket, int dayStep) {
  if (dayStep < 1 || dayStep > 31) {
    throw new IllegalArgumentException("Invalid dayStep value. Must be between 1 and 31.");
  }

  if (timeBucket < 0 || timeBucket > 999999999L) {
    throw new IllegalArgumentException("Invalid timeBucket value. Must be between 0 and 999999999L.");
  }

  int year = (int) (timeBucket / 10000L);
  int month = (int) ((timeBucket % 10000L) / 100L);
  int day = (int) (timeBucket % 100L);

  day = Math.min(day, dayStep * (month % 2 == 0 ? 1 : -1));
  day = Math.max(day, 1);

  int newTimeBucket = (year * 10000) + (month * 100) + day;

  return newTimeBucket;
