    // Check if the dayStep is valid
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }

    // Calculate the number of days to add to the time bucket
    int daysToAdd = (dayStep - 1) - (timeBucket % 100);

    // Check if the time bucket is in the same month
    if (daysToAdd < 0) {
        daysToAdd += 31;
    }

    // Add the calculated number of days to the time bucket
    return timeBucket + daysToAdd;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  // Step 1: Validate input
  if (str == null) {
    throw new IllegalArgumentException("String must not be null");
  }
  if (index < 0 || index >= str.length()) {
    throw new IndexOutOfBoundsException("Index out of bounds");
  }
  if (len < 0) {
    throw new IllegalArgumentException("Length must not be negative");
  }
  if (index + len > str.length()) {
    throw new IndexOutOfBoundsException("Index and length out of bounds");
  }

  // Step 2: Compute UTF8 size
  int size = 0;
  for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (c < 128) {
      size++;
    } else if (c < 2048) {
      size += 2;
    } else if (c < 65536) {
      size += 3;
    } else {
      size += 4;
    }
  }

  return size;
}

/**
 * Computes the size of the utf8 string beginning at the specified {@code index} with the specified {@code length}.
 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str cannot be null");
    }
    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("index is out of bounds");
    }
    if (len < 0) {
        throw new IllegalArgumentException("len cannot be negative");
    }

    int size = 0;
    for (int i = index; i < index + len && i < str.length(); i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            size += 4;
        } else {
            size += 3;
        }
    }

    return size;
}

