	int length = Math.min(len, str.length() - index);
	if (length <= 0) {
		throw new IllegalArgumentException("Length must be positive");
	}

	// Handle empty string input
	if (length == 0) {
		return 0;
	}

	// Compute UTF-8 string size
	int size = 0;
	for (int i = index; i < length; i++) {
