public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {

    // Step 1: Validate input parameters
    if (byteArrayValue == null && byteOffset != 0 && byteLength != 0) {
        throw new IllegalArgumentException("Input parameters are not valid: Byte array cannot be null, while byteOffset and byteLength are non-zero");
    }
    if (byteArrayValue != null && (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length)) {
        throw new IndexOutOfBoundsException("Input parameters are not valid: Byte offset and byte length must be non-negative and byte offset + byte length must be less than or equal to the length of the byte array");
    }

    // Step 2: Enlarge the byte vector if necessary
    if (byteArrayValue != null && byteOffset + byteLength > this.bytes.length) {
        this.enlarge(byteOffset + byteLength);
    }

    // Step 3: Copy the byte array into the byte vector
    if (byteArrayValue != null && byteLength > 0) {
        System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.position, byteLength);
    }

    // Step 4: Increment the position and return
    this.position += byteLength;
    return this;
}

