      // If byteArrayValue is null, fill this byte vector with null bytes
      for (int i = 0; i < byteLength; i++) {
          put(0);
      }
      return this;
   }

   // Check if byteOffset and byteLength are valid
   if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
      throw new IllegalArgumentException("byteOffset and byteLength must be valid");
   }

   // Put the bytes into this byte vector
   for (int i = byteOffset; i < byteOffset + byteLength; i++) {
      put(byteArrayValue[i]);
   }

   return this;
}

