public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb){

// Step 1: Check for null or empty string
if (str == null || str.length() == 0) {
throw new IllegalArgumentException("Input string is null or empty");
}

// Step 2: Check if LinkedBuffer is null
if (lb == null) {
throw new IllegalArgumentException("LinkedBuffer is null");
}

// Step 3: Check if WriteSession is null
if (session == null) {
throw new IllegalArgumentException("WriteSession is null");
}

// Step 4: Convert CharSequence to bytes using the UTF-8 charset
ByteBuffer bb;
try {
bb = StandardCharsets.UTF_8.encode(CharBuffer.wrap(str));
} catch (CharacterCodingException e) {
throw new IllegalArgumentException("Unable to encode string as UTF-8", e);
}

// Step 5: Write the bytes to the LinkedBuffer
lb.write(bb.array());

// Step 6: Update the LinkedBuffer
lb.updateLinks();

// Step 7: Return the LinkedBuffer
return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        byte[] bytes = str.getBytes(StandardCharsets.UTF_8);
        lb.write(bytes);
    } catch (IOException e) {
        throw new RuntimeException("Failed to write UTF-8 bytes", e);
    }

    return lb;
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws Exception {
	if (str.length() == 0) {
		throw new IOException("Input string is empty.");
	}

	// Bounds check
	if (lb.writableBytes() < (str.length() * 3)) {
		throw new IOException("Buffer is not large enough to hold the encoded string.");
	}

	for (int i = 0; i < str.length(); i++) {
		char c = str.charAt(i);
		if ((c >= 0x0000 && c <= 0x007F)) {
			lb.writeByte((byte) c);
		} else if (c > 0x07FF) {
			lb.writeByte((byte) (0xE0 | ((c >> 12) & 0x0F)));
			lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
			lb.writeByte((byte) (0x80 | (c & 0x3F)));
		} else {
			lb.writeByte((byte) (0xC0 | ((c >> 6) & 0x1F)));
			lb.writeByte((byte) (0x80 | (c & 0x3F)));
		}
	}

	return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        LinkedBuffer result = lb;
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            result = writeByte(c, session, result);
        }
        return result;
    } catch (IndexOutOfBoundsException e) {
        throw new RuntimeException("Invalid input string", e);
    }
}

/**
 * Writes the utf8-encoded bytes from the string into the  {@link LinkedBuffer}.
 */
public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session,final LinkedBuffer lb){
    // Early exit if the string is empty
    if (str.length() == 0) {
        return lb;
    }
    // Get the number of bytes required to encode the string
    final int byteCount = Charset.forName("UTF-8").encode(str, session.output(), session.output().position()).limit();
    // Allocate a new byte array to hold the encoded data
    final byte[] encoded = new byte[byteCount];
    // Write the encoded data into the LinkedBuffer
    lb.write(encoded, 0, byteCount);
    // Return the LinkedBuffer
    return lb;
}

