public static String findAndSubst(String key, Properties props) {
  // Check if key exists in properties
  if (!props.containsKey(key)) {
    throw new IllegalArgumentException("Key does not exist in properties");
  }

  // Get the value corresponding to the key
  String value = props.getProperty(key);

  // Perform variable substitution on the value
  value = substituteVariables(value, props);

  return value;
}

public static String substituteVariables(String value, Properties props) {
  // Iterate over the properties and substitute each variable found in the value
  for (String propName : props.stringPropertyNames()) {
    String propValue = props.getProperty(propName);
    value = value.replace("${" + propName + "}", propValue);
  }

  return value;
}

public static String findAndSubst(String key, Properties props) {
  // Step 1: Find the value corresponding to the given key in the properties object.
  String value = props.getProperty(key);

  // Step 2: Perform variable substitution on the found value.
  if (value != null) {
    Pattern p = Pattern.compile("\\$\\{([a-zA-Z0-9_]+)\\}");
    Matcher m = p.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
      String variable = m.group(1);
      String replacement = props.getProperty(variable);
      if (replacement != null) {
        m.appendReplacement(sb, replacement);
      } else {
        m.appendReplacement(sb, "\\$\\{" + variable + "\\}");
      }
    }
    m.appendTail(sb);
    value = sb.toString();
  }

  return value;
}

