 * Substitute variables in the given string with the values from the properties.
 */
public static String substitute(String value, Properties props) {
  if (value == null || props == null) {
    throw new IllegalArgumentException("Null parameter(s) provided");
  }

  Pattern pattern = Pattern.compile("\\$\\{[^}]+\\}");
