    }

    // Split the descriptor into segments.
    String[] segments = descriptor.split(";");
    if (segments.length == 0) {
        throw new IllegalArgumentException("Descriptor must contain at least one segment");
    }

    // Pop the appropriate number of types from the output frame stack.
    for (int i = 0; i < segments.length; i++) {
        String segment = segments[i];
        if (segment.isEmpty()) {
            throw new IllegalArgumentException("Segment " + i + " must not be empty");
        }

        if (segment.charAt(0) == '(') {
            // This is a method descriptor, pop its argument types.
            String[] argumentTypes = segment.substring(1, segment.length() - 1).split(",");
            for (int j = 0; j < argumentTypes.length; j++) {
                pop(argumentTypes[j]);
            }
        } else {
            // This is a type descriptor, pop the type.
            pop(segment);
        }
    }
}

