    }

    Type[] types = parseTypeOrMethodDescriptor(descriptor);
    for (int i = 0; i < types.length; i++) {
        Type type = types[i];
        if (type instanceof ReferenceType || type instanceof ArrayType) {
            StackFrame stackFrame = getOutputFrameStack().pop();
            if (stackFrame != null) {
                if (!(stackFrame.getType() instanceof ReferenceType) && !(stackFrame.getType() instanceof ArrayType)) {
                    throw new TypeCheckException("Unexpected type on stack");
