public void write(final byte b[], final int off, final int len) throws IOException {
    // Check if the input parameters are valid
    if (b == null || off < 0 || len < 0 || len > (b.length - off)) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Write the bytes to the output stream
    for (int i = 0; i < len; i++) {
        write(b[off + i]);
    }
}

@Override
public void write(final byte b[], final int off, final int len) throws IOException {
    // Edge case: null data
    if (b == null) {
        throw new NullPointerException("Data must not be null");
    }
    // Edge case: negative offset
    if (off < 0) {
        throw new IndexOutOfBoundsException("Offset must not be negative");
    }
    // Edge case: negative length
    if (len < 0) {
        throw new IndexOutOfBoundsException("Length must not be negative");
    }
    // Edge case: offset exceeds data length
    if (off > b.length) {
        throw new IndexOutOfBoundsException("Offset exceeds data length");
    }
    // Edge case: length exceeds data length
    if (len > b.length - off) {
        throw new IndexOutOfBoundsException("Length exceeds data length");
    }
    // Write the data to the output stream
    for (int i = off; i < len; i++) {
        write(b[i]);
    }
}

@Override
public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null || off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid input.");
    }
    for (int i = off; i < off + len; i++) {
        this.write(b[i]);
    }
}

/** 
 * Writes <code>len</code> bytes from the specified byte array starting at offset <code>off</code> to this byte array output stream.
 * @param b   the data.
 * @param off the start offset in the data.
 * @param len the number of bytes to write.
 */
@Override public void write(final byte b[],final int off,final int len) throws IOException {
  // Step 1: Check for null or empty input
  if (b == null || b.length == 0) {
    throw new IOException("Invalid input: byte array cannot be null or empty");
  }
  // Step 2: Check for valid offset and length
  if (off < 0 || off > b.length) {
    throw new IOException("Invalid offset: offset cannot be negative or greater than the length of the byte array");
  }
  if (len < 0 || len > b.length - off) {
    throw new IOException("Invalid length: length cannot be negative or greater than the remaining number of bytes in the byte array starting at the given offset");
  }
  // Step 3: Calculate the number of bytes to write
  int bytesToWrite = len - off;
  // Step 4: Check for enough room in the output stream
  if (bytesToWrite > available()) {
    throw new IOException("Insufficient space in the output stream: cannot write " + len + " bytes");
  }
  // Step 5: Write bytes to the output stream
  for (int i = 0; i < bytesToWrite; i++) {
    write(b[off + i]);
  }
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null || arr.length < 2) {
        throw new IllegalArgumentException("Invalid input array");
    }
    if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid index");
    }
    if (i != j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

