public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {

  // Step 1: Check if the LinkedBuffer is empty
  if (node == null) {
    return 0;
  }

  // Step 2: Initialize local variables
  LinkedBuffer current = node;
  int totalSize = 0;

  // Step 3: Iterate over the LinkedBuffer and write each node's content to the DataOutput
  while (current != null) {
    out.write(current.getContent());
    totalSize += current.getContent().length;
    current = current.getNext();
  }

  // Step 4: Return the total content size of the buffer
  return totalSize;
}

