}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("out and node must not be null");
    }

    int size = 0;

    for (Buffer current = node; current != null; current = current.getNext()) {
        if (current.getData() != null) {
            out.write(current.getData());
            size += current.getData().length;
        }
    }

    return size;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
  int totalSize = 0;
  while (node != null) {
    // write the current node's data to the output
    int currentSize = node.getData().size();
    out.write(node.getData().toByteArray());
    totalSize += currentSize;

    // move to the next node
    node = node.getNext();
  }
  return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
  int totalSize = 0;
  LinkedBuffer current = node;
  while (current != null) {
    totalSize += writeBuffer(out, current);
    current = current.getNext();
  }
  return totalSize;
}

private static int writeBuffer(DataOutput out, LinkedBuffer buffer) throws IOException {
  int size = 0;
  for (byte b : buffer.getBuffer()) {
    out.writeByte(b);
    size++;
  }
  return size;
}

