public String format(final LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("Logging event cannot be null.");
    }

    StringBuilder sb = new StringBuilder();

    // Timestamp
    sb.append(formatTimestamp(event.getTimeStamp()));

    // Severity
    sb.append(" ");
    sb.append(event.getLevel().toString());

    // Logger name
    sb.append(" ");
    sb.append(event.getLoggerName());

    // Thread name
    sb.append(" ");
    sb.append(event.getThreadName());

    // Message
    sb.append(" - ");
    sb.append(event.getMessage());

    // Exception
    if (event.getThrowableInformation() != null) {
        sb.append(" ");
        String exceptionMessage = event.getThrowableInformation().getMessage();
        if (exceptionMessage != null) {
            sb.append(exceptionMessage);
        }
    }

    // NDC
    if (event.getNDC() != null) {
        sb.append(" ");
        sb.append(event.getNDC());
    }

    return sb.toString();
}

/** 
 * Formats a logging event to a writer.
 * @param event logging event to be formatted.
 */
public String format(final LoggingEvent event){
  // Verify input parameters
  if (event == null) {
    throw new IllegalArgumentException("Logging event cannot be null");
  }

  // Initialize the output string
  StringBuilder output = new StringBuilder();

  // Format the timestamp
  output.append(event.getLevel().toUpperCase()).append(" [").append(event.getTimeStamp()).append("] - ");

  // Format the logger name
  output.append(event.getLogger().getName()).append(": ");

  // Format the message
  output.append(event.getMessage()).append('\n');

  // Format the throwable information (if present)
  if (event.getThrowable() != null) {
    output.append("Caused by: ").append(event.getThrowable().getMessage()).append('\n');
  }

  // Format the stack trace (if present)
  if (event.getStackTrace() != null) {
    output.append("Caused by: ").append(event.getStackTrace().getStackTraceInfo()).append('\n');
  }

  return output.toString();
}

public String format(final LoggingEvent event) {
    // Define the format string for the log message
    String format = "[%s] %s - %s";

    // Get the time, level, and message from the event
    String time = event.getTime();
    String level = event.getLevel();
    String message = event.getMessage();

    // Format the log message using the format string and the event data
    String formattedMessage = String.format(format, time, level, message);

    // Return the formatted message
    return formattedMessage;
}

public String format(final LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("Logging event cannot be null");
    }

    StringBuilder message = new StringBuilder();
    message.append("[").append(event.getLevel()).append("] ");

    // Format the timestamp
    String timestamp = event.getTimestamp();
    if (timestamp != null) {
        message.append(timestamp).append(" ");
    }

    // Format the logger name
    String loggerName = event.getLoggerName();
    if (loggerName != null) {
        message.append("(").append(loggerName).append(") ");
    }

    // Format the message
    String messageText = event.getMessage();
    if (messageText != null) {
        message.append(messageText).append(" ");
    }

    // Format the throwable
    Throwable throwable = event.getThrowable();
    if (throwable != null) {
        message.append("(Exception: ").append(throwable.getClass().getSimpleName()).append(") ");
        message.append(throwable.getMessage()).append(" ");
    }

    return message.toString();
}

