@Override
public void putAbstractTypes(int start, int end) {
  // Step 1: Validate input parameters

  // Check if start and end parameters are valid indices
  if (start < 0 || end < 0 || start >= currentFrame.size() || end > currentFrame.size()) {
    throw new IllegalArgumentException("Invalid start or end index provided");
  }

  // Check if currentFrame List is not empty
  if (currentFrame.isEmpty()) {
    throw new IllegalStateException("Current frame is empty");
  }

  // Step 2: Convert abstract types to verification_type_info format

  // Use variable to store the converted verification_type_info
  List<VerificationType> verificationTypes = new ArrayList<>();

  // Loop through all types in currentFrame
  for (int i = start; i < end; i++) {
    Type type = currentFrame.get(i);

    // Check if type is a primitive type or ClassTyoe
    if (type.getSort() == Type.P Cotinner.PRIMITIVE_INT) {
      verificationTypes.add(new PrimitiveType(type.getInternalName()));
    } else if (type.getSort() == Type.P Cotinner.CLASS_TYPE) {
      verificationTypes.add(new ClassType(type.getDescriptor()));
    } else {
      throw new UnknownTypeException("Unknown type encountered: " + type);
    }
  }

  // Step 3: Add verification_type_info to stackMapTableEntries

  // Use variable to store the stack size before adding the new verification_type_info
  int stackSize = stackMapTableEntries.size();

  // Add the verification_type_info to the stackMapTableEntries
  for (VerificationType verificationType : verificationTypes) {
    stackMapTableEntries.add(new StackMapTableEntry(verificationType, stackSize++));
  }
}

