import org.json.JSONWriter;

public String toString(JSONWriter.Feature... features) {
    try {
        StringBuilder sb = new StringBuilder();
        JSONWriter writer = new JSONWriter(sb);
        writer.beginObject();
        if (features.length > 0) {
            for (JSONWriter.Feature feature : features) {
                writer.writeKeyValue(feature.toString(), true);
            }
        }
        writer.endObject();
        return sb.toString();
    } catch (JSONException e) {
        throw new IllegalArgumentException("Unable to serialize JSON", e);
    }
}

public String toString(JSONWriter.Feature... features) {
    try {
        JSONWriter writer = new JSONWriter();
        writer.enable(features);
        writer.write(this);
        return writer.toString();
    } catch (JSONException e) {
        throw new IllegalArgumentException("Unable to serialize object: " + this, e);
    }
}

public String toString(JSONWriter.Feature... features) {
    try {
        JSONWriter writer = new JSONWriter();
        for (JSONWriter.Feature feature : features) {
            writer.enable(feature);
        }
        Object obj = writer.write(this);
        return obj.toString();
    } catch (JSONException e) {
        throw new RuntimeException("Failed to serialize to JSON", e);
    }
}

