 * @param type Data type to which this value should be converted.
 * @param value The input value to be converted.
 * @return The converted value.
 * @throws Exception if conversion cannot be performed successfully
 * @since 1.8.0
 */
@Override protected Object convertToType(final Class<?> type,Object value) throws Exception {
    // Validate input
    if (type == null) {
      throw new Exception("Invalid input: null data type provided");
    }
    if (value == null) {
      throw new Exception("Invalid input: null value provided");
    }
    // Convert value to Character
    if (type.isInstance(Character.class) || type.isInstance(Character.TYPE)) {
      try {
        String stringValue = String.valueOf(value);
        if (stringValue.length() == 1) {
          return (Character) stringValue.charAt(0);
        } else {
          throw new Exception("Invalid input: value must be a single character");
        }
      } catch (Exception e) {
        throw new Exception("Invalid input: could not convert value to Character");
      }
    } else {
      throw new Exception(
          "Invalid input: data type '" + type.getSimpleName() + "' cannot be converted to Character");
    }
  }

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("type cannot be null");
    }
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("type is not compatible with java.lang.Character");
    }
    if (value == null) {
        throw new IllegalArgumentException("value cannot be null");
    }
    if (!(value instanceof CharSequence)) {
        throw new IllegalArgumentException("value is not a CharSequence");
    }
    CharSequence charSequence = (CharSequence) value;
    if (charSequence.length() != 1) {
