protected Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Type cannot be null");
    } else if (!(type.isAssignableFrom(Character.class))) {
        throw new IllegalArgumentException("Invalid type, must be Character");
    } else if (value == null) {
        throw new IllegalArgumentException("Value cannot be null");
    } else if (!(value instanceof Character)) {
        throw new IllegalArgumentException("Invalid value, must be Character");
    }
    return (Character) value;
