private Character convertToCharacter(Object value) throws Exception {
    if (value instanceof Character) {
        return (Character) value;
    } else if (value instanceof String) {
        String stringValue = (String) value;
        if (stringValue.length() == 1) {
            return stringValue.charAt(0);
        } else {
            throw new Exception("Cannot convert string of length " + stringValue.length() + " to Character");
        }
    } else if (value instanceof Number) {
        Number numberValue = (Number) value;
        return (char) numberValue.intValue();
    } else {
        throw new Exception("Cannot convert " + value.getClass().getName() + " to Character");
    }
}

@Override
protected Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (!type.equals(Character.class)) {
        throw new Exception("Conversion to " + type.getName() + " is not supported");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return (Character) value;
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue < 0 || intValue > Character.MAX_VALUE) {
            throw new Exception("Value " + value + " is out of range for type Character");
        }
        return (char) intValue;
    }
    if (value instanceof String) {
        String stringValue = (String) value;
        if (stringValue.length() == 1) {
            return stringValue.charAt(0);
        }
    }
    throw new Exception("Conversion from " + value.getClass().getName() + " to type Character is not supported");
}

