/**
 * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
 * @param desiredCapacity the capacity desired by the user.
 * @return the capacity which should be used for a hashtable.
 */
public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("Desired capacity must be >= 2");
    }
    int prime = 2;
    while (prime < desiredCapacity) {
        if (isPrime(prime)) {
            return prime;
        }
        prime++;
    }
    throw new IllegalArgumentException("Unable to find prime number greater than or equal to " + desiredCapacity);
}

private static boolean isPrime(int number) {
    if (number < 2) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

/**
 * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000).
 * @param desiredCapacity the capacity desired by the user.
 * @return the capacity which should be used for a hashtable.
 */
public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 1) {
        return 1;
    }
    int capacity = (int) (desiredCapacity * 1.11);
    // check if the desiredCapacity is already prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }
    // iterate until we find a prime number within 11% of the desiredCapacity
    while (true) {
        if (isPrime(capacity)) {
            return capacity;
        }
        capacity++;
    }
}

