private static int digitValue(final char c) {
    if (!Character.isDigit(c)) {
        return -1;
    }

    int digitValue = Character.getNumericValue(c);
    if (digitValue >= 0 && digitValue <= 9) {
        return digitValue;
    } else if (digitValue >= 10 && digitValue <= 36) {
        return digitValue - 10;
    } else {
        return -1;
    }
}

/**
 * Interpret a character as a digit (in any base up to 36) and return the numeric value. This is like {@code Character.digit()} but we don't accept non-ASCII digits.
 */
private static int digitValue(final char c) {
    boolean isDigit = (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
    if (!isDigit) {
        throw new IllegalArgumentException("Invalid digit character: " + c);
    }
    int base = (c >= 'A' ? 10 : (c >= 'a' ? 10 + 26 : 0));
    return base + c - (c >= 'A' ? 'A' : (c >= 'a' ? 'a' : '0'));
}

private static int digitValue(final char c) {
    if (!Character.isDigit(c)) {
        throw new IllegalArgumentException("Invalid digit: " + c);
    }
    int digit = c - '0';
    if (digit < 0 || digit > 36) {
        throw new IllegalArgumentException("Digit out of range: " + c);
    }
    return digit;
}

