    List<Byte> bufferList = new ArrayList<>();

    // loop through each buffer and add its contents to the list
    for (ByteBuffer buffer : buffers) {
        bufferList.addAll(Arrays.asList(buffer.array()));
    }

    // convert the list to a byte array
    return bufferList.toArray(new byte[0]);
}

