public final byte[] toByteArray(){
    try{
        if(this.buffers.isEmpty()){
            return new byte[0];
        }
        else{
            int totalSize = 0;
            for(ByteBuffer buffer : this.buffers){
                totalSize += buffer.remaining();
            }

            byte[] result = new byte[totalSize];
            int index = 0;
            for(ByteBuffer buffer : this.buffers){
                int remaining = buffer.remaining();
                buffer.get(result, index, remaining);
                index += remaining;
            }

            return result;
        }
    }
    catch(BufferUnderflowException e){
        throw new IllegalArgumentException("Insufficient data to read", e);
    }
}

/** 
 * Returns a single byte array containg all the contents written to the buffer(s).
 */
public final byte[] toByteArray(){
    // Initialize an empty byte array with the total size of all the buffers
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
        totalSize += buffer.position();
    }
    byte[] result = new byte[totalSize];

    // Read each buffer and write its contents to the result array
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int length = buffer.position();
        buffer.flip();
        buffer.get(result, offset, length);
        offset += length;
    }

    return result;
}

