 */
private static String javaCharset(String charset){
  if (charset == null || charset.isEmpty()) {
    throw new IllegalArgumentException("Charset cannot be null or empty");
  }

  String javaCharset = null;
  switch (charset.toLowerCase()) {
    case "us-ascii":
      javaCharset = "ASCII";
      break;
    case "utf-8":
      javaCharset = "UTF-8";
      break;
    case "iso-8859-1":
      javaCharset = "ISO-8859-1";
      break;
    case "shift_jis":
      javaCharset = "Shift_JIS";
      break;
    case "euc-jp":
      javaCharset = "EUC_JP";
      break;
    default:
      throw new IllegalArgumentException("Unsupported charset: " + charset);
  }

  return javaCharset;
}

/** 
 * Translate a MIME standard character set name into the Java equivalent.
 * @param charset The MIME standard name.
 * @return The Java equivalent for this name.
 */
private static String javaCharset(String charset){
    if(charset.equals("US-ASCII")){
        return "ASCII";
    }else if(charset.equals("ISO-8859-1") || charset.equals("Latin1")){
        return "ISO-8859-1";
    }else if(charset.equals("UTF-8")){
        return "UTF-8";
    }else if(charset.equals("UTF-16")){
        return "UTF-16";
    }else if(charset.equals("UTF-16LE") || charset.equals("UTF-16BE")){
        return "UTF-16" + (charset.endsWith("LE") ? "LE" : "BE");
    }else{
        throw new IllegalArgumentException("Unsupported charset: " + charset);
    }
}

/** 
