 * @param charset The MIME standard name.
 * @return The Java equivalent for this name.
 */
private String javaCharset(String charset){
    String charSet = charset;
    if(!(charSet == null || charSet.isEmpty())){
        switch(charSet){
            case " ": case "9": charSet = "ISO-2022-JP";
            case "7": charSet = "ISO-8859-1";
            case "-": case "=": charSet = "ISO-8859-1";
            case "$": case "€": case "₹": charSet = "UTF-8";
            case "-": charSet = "UTF-7";
            case ".": charSet = "UTF-16";
            case "_": charSet = "UTF-32";
            case "~": charSet = "UTF-16BE";
            case "@": charSet = "UTF-16LE";
