 * @param set1 set 1
 * @param set2 set 2
 * @return intersection of set 1 and 2
 */
private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Check if both sets are null
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets cannot be null");
    }

    // Check if either set is empty
    if (set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<>();
    }

    // Create a new set to store the intersection
    Set<V> intersection = new HashSet<>();

    // Iterate over the elements of set1
    for (V element : set1) {
        // Check if the element is in set2
        if (set2.contains(element)) {
            intersection.add(element);
        }
    }

    return intersection;
}

