@Override
protected Object filter(Object msg) {
    // Get the BroadcastFilter annotation applied to this method
    Annotation annotation = this.getClass().getMethod(BroadcastFilter.class);
    if (annotation == null) {
        throw new RuntimeException("No BroadcastFilter annotation found on this method");
    }

    // Get the names of the recipients and the message to be sent
    String[] recipients = (String[]) annotation.getProperty("recipients");
    if (recipients.length == 0) {
        throw new RuntimeException("At least one recipient must be specified in the BroadcastFilter annotation");
    }

    String message = (String) annotation.getProperty("message");
    if (message == null || message.isEmpty()) {
        throw new RuntimeException("The message property must be specified in the BroadcastFilter annotation");
    }

    // Check if any of the recipients are registered with the ManagementFactory
    ManagementFactory factory = ManagementFactory.getManagementFactory();
    for (String recipient : recipients) {
        if (!factory.isRegistered(recipient)) {
            throw new RuntimeException("Recipient " + recipient + " is not registered with the ManagementFactory");
        }
    }

    // Invoke the BroadcastFilter
    BroadcastFilter filter = (BroadcastFilter) annotation.getValue();
    Object filteredMessage = filter.filter(message);

    // Check that the filtered message is valid
    if (!(filteredMessage instanceof byte[])) {
        throw new RuntimeException("The filtered message must be an instance of byte[]");
    }

    // Return the filtered message
    return filteredMessage;
}

