@Override
public int removeUnusedNodes() {
  // Step 1: Identify all inactive nodes
  List<Category> unusedNodes = new ArrayList<>();
  for (Category node : getNodes()) {
    if (!node.isActive()) {
      unusedNodes.add(node);
    }
  }

  // Step 2: Remove inactive nodes from the tree
  for (Category node : unusedNodes) {
    // If the node has children, re-parent them to their grandparents
    if (node.getChildren() != null) {
      for (Category child : node.getChildren()) {
        child.setParent(node.getParent());
      }
    }
    // Remove the node from its parent's list of children
    if (node.getParent() != null) {
      node.getParent().getChildren().remove(node);
    }
    // Remove the node from the tree
    getNodes().remove(node);
  }

  return unusedNodes.size();
}

