    // check if the resource's transport is suspended
    if (r.getTransport().isSuspended()) {
        // if suspended, log a message and return Action.CONTINUE
        logger.info("AtmosphereResource transport is already suspended");
        return Action.CONTINUE;
    }
    // otherwise, suspend the resource's transport and return Action.CONTINUE
    try {
        r.getTransport().suspend();
    } catch (Exception e) {
        logger.error("Error suspending AtmosphereResource transport", e);
        return Action.ABORT;
    }
    return Action.CONTINUE;
}

