protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
  // check if tour is empty
  if(tour.isEmpty()){
    return null;
  }

  // check if the tour is a valid path in the graph
  if(!isValidTour(tour, graph)){
    throw new IllegalArgumentException("The tour is not a valid path in the graph");
  }

  // create a new graph path
  GraphPath<V,E> path = new GraphPath<V,E>();

  // add the vertices and edges of the tour to the graph path
  for(E edge : tour){
    path.addVertex(graph.getEdgeSource(edge));
    path.addVertex(graph.getEdgeTarget(edge));
    path.addEdge(edge);
  }

  // return the graph path
  return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Step 1: Convert the edge set to a list of edges
    List<E> edgeList = new ArrayList<E>(tour);

    // Step 2: Sort the edge list by their source vertex
    Collections.sort(edgeList, new Comparator<E>() {
        @Override
        public int compare(E e1, E e2) {
            return graph.getEdgeSource(e1).compareTo(graph.getEdgeSource(e2));
        }
    });

    // Step 3: Create a new path based on the sorted edge list
    GraphPath<V,E> path = new GraphPath<V,E>(graph);
    for (E edge : edgeList) {
        path.addEdge(edge);
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour == null || graph == null){
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if(tour.size() < 2){
        throw new IllegalArgumentException("Tour must contain at least 2 edges");
    }
    if(tour.size() > graph.getVertexCount()){
        throw new IllegalArgumentException("Tour size must be less than or equal to the number of vertices in the graph");
    }

    // create a map of edges to vertices
    Map<E,V> edgeVertexMap = new HashMap<>();
    for(E edge : tour){
        if(!edgeVertexMap.contains(edge)){
            edgeVertexMap.put(edge, graph.getVertices(edge));
        }
    }

    // create a map of vertices to edges
    Map<V,Set<E>> vertexEdgeMap = new HashMap<>();
    for(V vertex : graph.getVertices()){
        Set<E> edges = new HashSet<>();
        for(E edge : edgeVertexMap.get(vertex)){
            edges.add(edge);
        }
        vertexEdgeMap.put(vertex, edges);
    }

    // create a map of edges to vertices in the tour
    Map<E,V> tourEdgeMap = new HashMap<>();
    for(E edge : tour){
        tourEdgeMap.put(edge, edgeVertexMap.get(edge));
    }

    // create a graph path
    GraphPath<V,E> path = new GraphPath<>();
    path.setStart(graph.getVertices().iterator().next());

    // traverse the tour and add vertices and edges to the path
    for(E edge : tour){
        V vertex = edgeVertexMap.get(edge);
        path.addEdge(edge);
        path.addVertex(vertex);
    }

    return path;
}

