public static String stripFilenameExtension(String path){
    // Check if the path is null or empty
    if (path == null || path.isEmpty()){
        return null;
    }

    // Find the last separator (either '\' or '/')
    int lastSeparatorIndex = path.lastIndexOf('/');
    if (lastSeparatorIndex == -1){
        lastSeparatorIndex = path.lastIndexOf('\\');
    }

    // If there is no separator, return null
    if (lastSeparatorIndex == -1){
        return null;
    }

    // Find the last '.' (if any)
    int lastDotIndex = path.lastIndexOf('.');

    // If there is no '.' or it's before the last separator, return null
    if (lastDotIndex == -1 || lastDotIndex < lastSeparatorIndex){
        return null;
    }

    // Strip the filename extension
    String result = path.substring(0, lastDotIndex);

    return result;
}

