        if (bounds == null || bounds.isEmpty()) {
            throw new IllegalArgumentException("Bounds list must not be null or empty");
        }

        // Initialize suffix sum and sum of all elements in the bounds list
        List<Integer> suffixSum = new ArrayList<>(bounds.size());
        long sum = 0L;

        // Compute suffix sum and sum of all elements in the bounds list
        for (int i = 0; i < bounds.size(); i++) {
            int value = bounds.get(i);
            suffixSum.add(sum);
            sum += value;
        }

        // Return computed suffix sum and sum of all elements in the bounds list
        return new Pair<>(suffixSum, sum);
    }
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty");
    }
    List<Integer> suffixSums = new ArrayList<>();
    long sum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int bound = bounds.get(i);
        sum += bound;
        suffixSums.add(sum);
    }
    return Pair.create(suffixSums, sum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("The input array cannot be null.");
    }
    if (from < 0 || from >= arr.length || to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("The specified range is out of bounds.");
    }
    if (from > to) {
        throw new IllegalArgumentException("The specified range is invalid.");
    }
    int length = to - from + 1;
    for (int i = 0; i < length / 2; i++) {
        V temp = arr[from + i];
        arr[from + i] = arr[to - i];
        arr[to - i] = temp;
    }
}

/** 
 * Reverses the order of the elements in the specified range within the given array.
 * @param < V > the type of elements in the array
 * @param arr the array
 * @param from the index of the first element (inclusive) inside the range to reverse
 * @param to the index of the last element (inclusive) inside the range to reverse
 */
public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty.");
    }
    if (from < 0 || from >= arr.length) {
        throw new IllegalArgumentException("From index must be a valid index in the array.");
    }
    if (to < 0 || to >= arr.length) {
        throw new IllegalArgumentException("To index must be a valid index in the array.");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to the to index.");
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

/** 
