 * @param to the index of the last element (inclusive) inside the range to reverse
 */
public static final <V>void reverse(V[] arr, int from, int to) {
    // Checking the validity of the method parameters
    if (arr == null || arr.length == 0 || from < 0 || to > arr.length || from > to) {
        throw new IllegalArgumentException("Invalid method parameters");
    }

    // Swapping the elements in the specified range
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
