        return;
    }
    if (this.isEmpty()) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.setNext(list.head);
        list.head.setPrevious(this.tail);
        this.tail = list.tail;
    }
    list.head = null;
    list.tail = null;
}

