public void moveAllListNodes(DoublyLinkedList<E> list) {
    // Step 1: Check if the input list is null or empty
    if (list == null || list.isEmpty()) {
        return;
    }

    // Step 2: Iterate through the input list and remove each node with "removeListNode"
    ListNode<E> currentNode = list.getFirst();
    while (currentNode != null) {
        ListNode<E> nextNode = currentNode.getNext();
        removeListNode(currentNode);
        currentNode = nextNode;
    }

    // Step 3: Add each node to this list with "addListNode"
    currentNode = list.getFirst();
    while (currentNode != null) {
        addListNode(currentNode);
        currentNode = currentNode.getNext();
    }
}

