public static String base64Decode(final String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null.");
    }
    if (s.isEmpty()) {
        return "";
    }
    StringBuilder decodedString = new StringBuilder();
    int remainder = s.length() % 4;
    if (remainder > 0) {
        String padding = "====".substring(0, 4 - remainder);
        s = s + padding;
    }
    for (int i = 0; i < s.length(); i += 4) {
        String block = s.substring(i, i + 4);
        byte[] bytes = new byte[3];
        for (int j = 0; j < 4; j++) {
            int base64Char = BASE64_ALPHABET.indexOf(block.charAt(j));
            if (base64Char == -1) {
                throw new IllegalArgumentException("Input string contains invalid characters.");
            }
            bytes[j] = (byte) (base64Char & 0xFF);
        }
        byte[] decodedBytes = Base64.getDecoder().decode(bytes);
        decodedString.append(new String(decodedBytes));
    }
    return decodedString.toString();
}

