public void abbreviate(final int nameStart, final StringBuffer buf) {
    String name = buf.substring(nameStart);
    if (name.isEmpty()) {
        return;
    }
    String[] words = name.split("\\s+");
    if (words.length == 0) {
        return;
    }
    String abbreviation = "";
    for (String word : words) {
        abbreviation += word.charAt(0);
    }
    buf.replace(nameStart, nameStart + name.length(), abbreviation);
}

/** 
 * Abbreviate name.
 * @param buf buffer to append abbreviation.
 * @param nameStart start of name to abbreviate.
 */
public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
        return;
    }
    int nameEnd = buf.length();
    for (int i = nameStart; i < nameEnd; i++) {
        char c = buf.charAt(i);
        if (Character.isWhitespace(c)) {
            break;
        }
        nameEnd = i + 1;
    }
    buf.delete(nameStart, nameEnd);
}

