	}
	if (nameStart < 0 || nameStart >= buf.length()) {
		throw new IllegalArgumentException("Invalid nameStart index: " + nameStart);
	}

	String name = buf.substring(nameStart);
	String[] words = name.split(" ");
	StringBuilder sb = new StringBuilder();
	sb.append(words[0].substring(0, 1));

	// Loop through the remaining words
	for (int i = 1; i < words.length; i++) {
		String word = words[i];
		if (word.length() > 0 && word.charAt(0) != '.') {
			sb.append(word.substring(0, 1));
		}
	}

	buf.replace(nameStart, buf.length(), sb.toString());
}

