 */
public void abbreviate(final int nameStart,final StringBuffer buf){
  // Initialize variable for checking if the first letter has been abbreviated
  boolean firstLetterAbbreviated = false;
  // Loop through each character in the name starting from the given start position
  for (int i = nameStart; i < buf.length(); i++) {
    // If the current character is a letter and it is not the first letter,
    // Check if the previous character is a space or the first letter has already been abbreviated
    if (Character.isLetter(buf.charAt(i)) && (i == nameStart || buf.charAt(i - 1) == ' ' || firstLetterAbbreviated)) {
      // If the previous character is a space, set the first letter flag to true
      if (buf.charAt(i - 1) == ' ') {
        firstLetterAbbreviated = true;
      }
      // Append the uppercase version of the current character to the buffer
      buf.append(Character.toUpperCase(buf.charAt(i)));
    }
  }
}

