/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // step 1: check if the input graph and vertices are valid
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false;
    }

    // step 2: check if the induced subgraph is complete
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (vertices.contains(v2) && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    // step 3: check if the induced subgraph is a clique
    for (E edge : graph.getEdges()) {
        if (!vertices.contains(graph.getEdgeSource(edge)) || !vertices.contains(graph.getEdgeTarget(edge))) {
            return false;
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }
    V u = vertices.iterator().next();
    for (V v : vertices) {
        if (!graph.adjacent(u, v)) {
            return false;
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Step 1: Create a new graph with the same vertex set as the original graph
    Graph<V, E> subgraph = new Graph<>(graph.getVertexSet());

    // Step 2: Add all edges from the original graph that connect two vertices in the vertex set
    for (E edge : graph.getEdges()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (vertices.contains(source) && vertices.contains(target)) {
            subgraph.addEdge(source, target, edge);
        }
    }

    // Step 3: Check if the subgraph is a clique
    return subgraph.isClique();
}

