public class TcpAppender extends AppenderSkeleton {

    // each client's socket
    private List<Socket> sockets = new ArrayList<>();

    // lock to ensure single-threaded access to the sockets list
    private final Object socketsLock = new Object();

    // creates a new TcpAppender
    public TcpAppender() {
        this.sockets = new ArrayList<>();
    }

    // adds a socket to the list of connected clients
    public void addSocket(Socket socket) {
        synchronized (socketsLock) {
            if (!sockets.contains(socket)) {
                sockets.add(socket);
            }
        }
    }

    // removes a socket from the list of connected clients
    public void removeSocket(Socket socket) {
        synchronized (socketsLock) {
            if (sockets.contains(socket)) {
                sockets.remove(socket);
            }
        }
    }

    // returns the number of connected clients
    public int getConnectedClientCount() {
        synchronized (socketsLock) {
            return sockets.size();
        }
    }

    // appends a log event
    protected void append(LoggingEvent event) {
        synchronized (socketsLock) {
            for (Socket socket : sockets) {
                try {
                    // write the log event to the socket
                    socket.getOutputStream().write(event.getBytes());
                } catch (IOException e) {
                    // if there's an error writing to the socket,
                    // remove it from the list of connected clients
                    removeSocket(socket);
                }
            }
        }
    }
}

