public int readTag() throws IOException {
    // Step 1: Check if we have reached EOF
    if (inputStream.available() == 0) {
        return 0;
    }

    // Step 2: Read the first byte of the tag
    int firstByte = inputStream.read();
    if (firstByte == -1) {
        // If we have reached EOF, return 0
        return 0;
    }

    // Step 3: Check if the first byte is a valid tag
    if (firstByte < 16) {
        // If the first byte is less than 16, it is not a valid tag
        throw new IOException("Invalid tag: " + firstByte);
    }

    // Step 4: Read the second byte of the tag
    int secondByte = inputStream.read();
    if (secondByte == -1) {
        // If we have reached EOF, return 0
        return 0;
    }

    // Step 5: Combine the first and second byte to form the tag
    int tag = (firstByte << 8) | secondByte;

    // Step 6: Check if the tag is valid
    if (tag == 0 || tag >= 0xFFFF) {
        // If the tag is 0 or greater than or equal to 0xFFFF, it is not a valid tag
        throw new IOException("Invalid tag: " + tag);
    }

    // Step 7: Return the tag
    return tag;
}

