private static ThreadSnapshot parseThreadSnapshot(String line) {
    String[] tokens = line.split(",");
    if (tokens.length < 3) {
        return null;
    }

    long timestamp = Long.parseLong(tokens[0]);
    int state = Integer.parseInt(tokens[1]);
    int[] stackTrace = new int[tokens.length - 2];
    for (int i = 2; i < tokens.length; i++) {
        stackTrace[i - 2] = Integer.parseInt(tokens[i]);
    }
    return new ThreadSnapshot(timestamp, state, stackTrace);
}

